INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, description, example_sentence) VALUES
  ('SWOT分析', 'スウォットぶんせき', 'SWOT 분석', 'SWOT Analysis', 'business', '강점(Strength), 약점(Weakness), 기회(Opportunity), 위협(Threat)을 분석하여 경영 전략을 세우는 기법입니다.', 'SWOT分析を行って新規事業の方向性を検討しましょう。'),
  ('ROI', 'アールオーアイ', 'ROI', 'Return on Investment', 'business', '투자한 비용에 대해 얼마나 이익을 얻었는지를 나타내는 지표입니다.', 'システム導入のROIを算出して投資判断の材料にします。'),
  ('SaaS', 'サース', 'SaaS', 'Software as a Service', 'business', '인터넷을 통해 소프트웨어를 서비스로 제공하는 형태입니다. 설치 없이 바로 사용할 수 있습니다.', 'SaaS型のサービスを導入して初期コストを抑えました。'),
  ('PaaS', 'パース', 'PaaS', 'Platform as a Service', 'business', '애플리케이션 개발에 필요한 플랫폼(실행 환경, DB 등)을 인터넷을 통해 제공하는 서비스입니다.', 'PaaSを利用してアプリケーションの開発環境を構築しました。'),
  ('IaaS', 'イアース', 'IaaS', 'Infrastructure as a Service', 'business', '서버, 스토리지, 네트워크 등 IT 인프라를 인터넷을 통해 제공하는 서비스입니다.', 'IaaSを活用してサーバーインフラを柔軟に構築しています。'),
  ('知的財産権', 'ちてきざいさんけん', '지적 재산권', 'Intellectual Property Rights', 'business', '발명, 저작물, 상표 등 인간의 지적 창작물에 대한 법적 권리의 총칭입니다.', '知的財産権を適切に管理してビジネスの競争力を守りましょう。'),
  ('コンプライアンス', 'コンプライアンス', '컴플라이언스', 'Compliance', 'business', '법령이나 사회 규범을 준수하는 것입니다. 기업 경영에서 매우 중요한 개념입니다.', 'コンプライアンス研修を全社員に実施しています。'),
  ('個人情報保護法', 'こじんじょうほうほごほう', '개인정보보호법', 'Personal Information Protection Act', 'business', '개인정보의 취급에 관한 규칙을 정한 법률입니다. 사업자가 지켜야 할 의무를 규정합니다.', '個人情報保護法に基づいてデータの取り扱いルールを定めています。'),
  ('損益分岐点', 'そんえきぶんきてん', '손익분기점', 'Break-Even Point', 'business', '매출과 비용이 같아져 이익도 손실도 없는 지점입니다. 이 이상 팔면 이익이 발생합니다.', '損益分岐点を計算してプロジェクトの採算性を評価します。'),
  ('RFP', 'アールエフピー', 'RFP', 'Request for Proposal', 'business', '시스템 도입 시 발주자가 공급자에게 제안을 요청하는 문서입니다.', 'RFPを作成してベンダーに提案を依頼しました。'),
  ('NDA', 'エヌディーエー', 'NDA', 'Non-Disclosure Agreement', 'business', '비밀정보를 외부에 공개하지 않기로 약속하는 비밀유지 계약서입니다.', 'プロジェクト開始前にNDAを締結してください。'),
  ('著作権', 'ちょさくけん', '저작권', 'Copyright', 'business', '문학, 음악, 소프트웨어 등 창작물에 대해 창작자가 갖는 법적 권리입니다.', '他社のソースコードには著作権があるため無断使用はできません。'),
  ('特許権', 'とっきょけん', '특허권', 'Patent Right', 'business', '새로운 발명에 대해 일정 기간 독점적으로 사용할 수 있는 권리입니다.', '新しいアルゴリズムについて特許権を取得しました。'),
  ('商標権', 'しょうひょうけん', '상표권', 'Trademark Right', 'business', '상품이나 서비스의 이름, 로고 등을 독점적으로 사용할 수 있는 권리입니다.', '自社ブランドの商標権を登録して保護しています。'),
  ('CSR', 'シーエスアール', 'CSR', 'Corporate Social Responsibility', 'business', '기업이 사회적 책임을 다하기 위해 수행하는 활동입니다. 환경 보호, 사회 공헌 등이 포함됩니다.', 'CSR活動として地域のIT教育支援を行っています。'),
  ('ESG', 'イーエスジー', 'ESG', 'Environmental Social Governance', 'business', '환경(E), 사회(S), 지배구조(G)를 고려한 기업 경영 방식입니다. 투자 판단의 기준이 됩니다.', 'ESG経営を推進して持続可能な成長を目指しています。'),
  ('DX', 'ディーエックス', 'DX', 'Digital Transformation', 'business', '디지털 기술을 활용하여 기업의 업무 방식이나 비즈니스 모델을 근본적으로 변혁하는 것입니다.', 'DXを推進して業務プロセスのデジタル化を進めています。'),
  ('AI', 'エーアイ', 'AI', 'Artificial Intelligence', 'business', '인간의 지능적인 행동을 컴퓨터로 구현하는 기술입니다. 학습, 판단, 예측 등이 가능합니다.', 'AIを活用して業務の自動化と効率化を図っています。'),
  ('BI', 'ビーアイ', 'BI', 'Business Intelligence', 'business', '축적된 데이터를 분석하여 경영 의사결정에 활용하는 도구와 방법론입니다.', 'BIツールを使って売上データを可視化して分析しています。'),
  ('ERP', 'イーアールピー', 'ERP', 'Enterprise Resource Planning', 'business', '기업의 경영 자원(인사, 회계, 생산 등)을 통합적으로 관리하는 시스템입니다.', 'ERPを導入して社内の業務プロセスを統合管理しています。'),
  ('CRM', 'シーアールエム', 'CRM', 'Customer Relationship Management', 'business', '고객과의 관계를 체계적으로 관리하여 고객 만족도와 매출을 높이는 경영 기법입니다.', 'CRMシステムで顧客情報を一元管理しています。'),
  ('SCM', 'エスシーエム', 'SCM', 'Supply Chain Management', 'business', '원재료 조달부터 생산, 유통, 판매까지의 공급 과정을 전체적으로 관리하는 경영 기법입니다.', 'SCMを最適化してコスト削減とリードタイム短縮を実現しました。'),
  ('FinTech', 'フィンテック', '핀테크', 'FinTech', 'business', '금융(Finance)과 기술(Technology)을 결합한 새로운 금융 서비스입니다.', 'FinTech企業との連携で新しい決済サービスを開発しています。'),
  ('RPA', 'アールピーエー', 'RPA', 'Robotic Process Automation', 'business', '사무 작업을 소프트웨어 로봇이 자동으로 수행하도록 하는 기술입니다.', 'RPAを導入して定型業務を自動化し、業務効率を向上させました。'),
  ('アウトソーシング', 'アウトソーシング', '아웃소싱', 'Outsourcing', 'business', '자사의 업무 일부를 외부 전문 업체에 위탁하는 경영 방식입니다.', 'IT運用をアウトソーシングしてコア業務に集中しています。'),
  ('BPO', 'ビーピーオー', 'BPO', 'Business Process Outsourcing', 'business', '기업의 업무 프로세스 전체를 외부에 위탁하는 것입니다. 단순 위탁보다 범위가 넓습니다.', '経理業務をBPOに委託して社内リソースを最適化しました。'),
  ('M&A', 'エムアンドエー', 'M&A', 'Mergers and Acquisitions', 'business', '기업의 합병(Merger)과 인수(Acquisition)를 통한 경영 전략입니다.', 'M&Aによって新たな技術力と顧客基盤を獲得しました。'),
  ('IR', 'アイアール', 'IR', 'Investor Relations', 'business', '기업이 투자자에게 경영 상황이나 재무 정보를 제공하는 활동입니다.', 'IR資料を作成して投資家向けに四半期決算を報告します。'),
  ('内部統制', 'ないぶとうせい', '내부 통제', 'Internal Control', 'business', '기업 내부에서 업무가 적절하게 수행되도록 관리하는 체계입니다. 부정 방지와 업무 효율화를 목적으로 합니다.', '内部統制を強化して不正リスクを低減させます。'),
  ('コーポレートガバナンス', 'コーポレートガバナンス', '기업 지배구조', 'Corporate Governance', 'business', '기업 경영을 감시하고 통제하는 체계입니다. 경영의 투명성과 건전성을 확보합니다.', 'コーポレートガバナンスを強化して経営の透明性を向上させています。'),
  ('リスクマネジメント', 'リスクマネジメント', '리스크 관리', 'Risk Management', 'business', '잠재적인 위험을 사전에 파악하고, 대응 방안을 수립하여 손실을 최소화하는 활동입니다.', 'リスクマネジメントを徹底してプロジェクトの成功確率を高めましょう。'),
  ('PDCAサイクル', 'ピーディーシーエーサイクル', 'PDCA 사이클', 'PDCA Cycle', 'business', '계획(Plan), 실행(Do), 확인(Check), 개선(Act)을 반복하여 업무를 지속적으로 개선하는 방법입니다.', 'PDCAサイクルを回して業務品質を継続的に改善しています。'),
  ('KGI', 'ケージーアイ', 'KGI', 'Key Goal Indicator', 'business', '최종 목표의 달성 여부를 판단하기 위한 핵심 지표입니다. KPI와 함께 사용됩니다.', 'KGIとして年間売上目標を設定しました。'),
  ('OKR', 'オーケーアール', 'OKR', 'Objectives and Key Results', 'business', '조직의 목표(Objective)와 그것을 측정하는 핵심 결과(Key Result)를 설정하는 목표 관리 기법입니다.', 'OKRを導入してチームの目標を明確にしました。'),
  ('バリューチェーン', 'バリューチェーン', '가치 사슬', 'Value Chain', 'business', '기업의 활동을 원재료 조달부터 판매까지 단계별로 나누어 각 단계에서 창출되는 가치를 분석하는 기법입니다.', 'バリューチェーン分析を行って競争優位を明確にしましょう。'),
  ('マーケティングミックス', 'マーケティングミックス', '마케팅 믹스', 'Marketing Mix', 'business', '제품(Product), 가격(Price), 유통(Place), 판촉(Promotion)의 4가지 요소를 조합하여 마케팅 전략을 수립하는 것입니다.', 'マーケティングミックスの4Pを分析して戦略を立案します。'),
  ('ブルーオーシャン戦略', 'ブルーオーシャンせんりゃく', '블루오션 전략', 'Blue Ocean Strategy', 'business', '경쟁이 없는 새로운 시장을 개척하여 높은 수익을 창출하는 경영 전략입니다.', 'ブルーオーシャン戦略で未開拓の市場を狙います。'),
  ('競争優位', 'きょうそうゆうい', '경쟁 우위', 'Competitive Advantage', 'business', '경쟁 기업보다 우월한 위치를 차지하여 더 높은 수익을 올릴 수 있는 상태입니다.', '独自の技術力を活かして競争優位を確立しています。'),
  ('イノベーション', 'イノベーション', '혁신', 'Innovation', 'business', '기존과는 다른 새로운 기술이나 아이디어를 도입하여 큰 변화를 일으키는 것입니다.', 'イノベーションを推進して新しいビジネスモデルを構築します。'),
  ('ベンチマーキング', 'ベンチマーキング', '벤치마킹', 'Benchmarking', 'business', '우수한 기업의 사례를 분석하고 자사에 적용하여 경쟁력을 높이는 경영 기법입니다.', '業界トップ企業をベンチマーキングして改善点を洗い出しました。'),
  ('フィージビリティスタディ', 'フィージビリティスタディ', '타당성 조사', 'Feasibility Study', 'business', '프로젝트나 사업의 실현 가능성을 사전에 조사하고 평가하는 활동입니다.', 'フィージビリティスタディを行って事業化の可否を判断します。'),
  ('標準化', 'ひょうじゅんか', '표준화', 'Standardization', 'business', '제품이나 프로세스의 규격을 통일하여 효율성과 호환성을 높이는 활동입니다.', '業務プロセスの標準化を進めて効率を向上させましょう。'),
  ('ISO', 'アイエスオー', 'ISO', 'International Organization for Standardization', 'business', '국제 표준화 기구로, 다양한 분야의 국제 규격을 제정합니다.', 'ISO認証を取得して品質管理体制を証明しています。'),
  ('ISMS', 'アイエスエムエス', 'ISMS', 'Information Security Management System', 'business', '조직의 정보 보안을 체계적으로 관리하기 위한 프레임워크입니다. ISO 27001이 대표적 기준입니다.', 'ISMSの認証を取得してセキュリティ管理体制を強化しました。'),
  ('プライバシーマーク', 'プライバシーマーク', '프라이버시 마크', 'Privacy Mark', 'business', '개인정보를 적절히 관리하고 있음을 인증하는 일본의 제도입니다.', 'プライバシーマークを取得してお客様の信頼を得ています。'),
  ('不正競争防止法', 'ふせいきょうそうぼうしほう', '부정경쟁방지법', 'Unfair Competition Prevention Act', 'business', '영업 비밀 침해, 모방품 판매 등 부정한 경쟁 행위를 금지하는 법률입니다.', '不正競争防止法に基づいて営業秘密の管理を徹底しています。'),
  ('労働基準法', 'ろうどうきじゅんほう', '노동기준법', 'Labor Standards Act', 'business', '근로자의 근로 조건에 관한 최저 기준을 정한 법률입니다. 근무 시간, 휴일, 급여 등을 규정합니다.', '労働基準法に基づいて残業時間を適切に管理してください。'),
  ('下請法', 'したうけほう', '하도급법', 'Subcontract Act', 'business', '발주 기업이 하도급 업체에 대해 부당한 행위를 하지 못하도록 규제하는 법률입니다.', '下請法を遵守して外注先との適正な取引を行います。'),
  ('電子契約', 'でんしけいやく', '전자 계약', 'Electronic Contract', 'business', '종이 대신 전자적 방식으로 계약을 체결하는 것입니다. 전자 서명을 사용합니다.', '電子契約を導入して契約手続きの効率化とペーパーレス化を実現しました。')
